/**
 * Free-text entry of several values, shown as chips (`design/components/tag-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tag-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  createComputed,
  createMemo,
  createSignal,
  createUniqueId,
  mergeProps,
  on,
  onCleanup,
  onMount,
  type JSX,
} from 'solid-js'

import {
  Each,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/tag-input.module.css'
import TagInputChip from './TagInputChip'

export interface TagInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string[]
  disabled?: boolean
  id?: string
  invalid?: boolean
  /**
   * At the maximum the field is read-only, not removed and not disabled. A full field is still
   * what FormField's label points at, and keyboard users can still reach it. It blocks typing,
   * not access.
   */
  max?: number
  /**
   * Serialises comma-joined into a hidden input, for a native form post.
   */
  name?: string
  /**
   * Fires when focus leaves the whole field, for touched validation. Chips and input are one
   * control, so moving focus between them is not a blur. Only leaving the field is.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (values: string[]) => void
  /**
   * Shown only while empty. The chips are the value, and a placeholder beside them is clutter.
   */
  placeholder?: string
  /**
   * The accessible name of a chip's remove button. It is a function because the tag is data and
   * the text around it comes from the app's message catalog. Defaults to `Remove {tag}`.
   */
  removeLabel?: (tag: string) => string
  size?: 'sm' | 'md' | 'lg'
  /**
   * Normalize or reject: return the tag as it should be stored, or `null` to reject it. A
   * rejection flashes the container and shows no message. Persistent written errors come from
   * FormField.
   */
  validate?: (raw: string) => string | null
  value?: string[]
}

/** Free-text entry of several values, shown as chips. */
export default function TagInput(given: TagInputProps): JSX.Element {
  const props = mergeProps(
    {
      validate: (raw: string) => (raw.trim() === '' ? null : raw.trim()),
      size: 'md',
      disabled: false,
      invalid: false,
      removeLabel: (tag: string) => `Remove ${tag}`,
    } as Defaults<TagInputProps, 'validate' | 'size' | 'disabled' | 'invalid' | 'removeLabel'>,
    claimSlot(given, 'field'),
  )
  return scope(() => {
    const uid = createUniqueId()
    const uncontrolled = createCell(props.defaultValue ?? [])
    const draft = createCell('')
    const flashing = createCell(null as string | null)
    const refused = createCell(false)
    const announcement = createCell('')
    const settled = createCell(false)
    const chipList = elementRef<HTMLElement>()
    const field = elementRef<HTMLElement>()
    const values = createDerived(() => props.value ?? uncontrolled.value)
    const atMax = createDerived(() => props.max !== undefined && values.value.length >= props.max)
    const countId = createDerived(() => `${props.id ?? uid}-count`)
    const commit = createDerived(() => (next: string[]) => {
      uncontrolled.value = next
      props.onChange?.(next)
    })
    const add = createDerived(() => (raws: string[]) => {
      const next = [...values.value]
      let refusal = false
      let duplicate: string | null = null
      for (const raw of raws) {
        if (props.max !== undefined && next.length >= props.max) break
        const tag = props.validate(raw)
        if (tag === null) {
          refusal = true
          continue
        }
        if (next.includes(tag)) {
          duplicate = tag
          continue
        }
        next.push(tag)
      }
      refused.value = refusal
      flashing.value = duplicate
      if (next.length !== values.value.length) commit.value(next)
    })
    const removeButton = createDerived(
      () => (at: number) =>
        chipList.value?.querySelectorAll<HTMLElement>(':scope > li:not([data-removing]) button')[
          at
        ] ?? null,
    )
    const remove = createDerived(() => (tag: string) => {
      const before = values.value
      const at = before.indexOf(tag)
      const target = at === -1 || at + 1 >= before.length ? null : removeButton.value(at + 1)
      commit.value(before.filter((other) => other !== tag))
      announcement.value = `${tag} removed, ${before.length - 1} remain`
      if (target) target.focus()
      else field.value?.focus()
    })
    const receive = createDerived(() => (event: Event) => {
      draft.value = (event.target as HTMLInputElement).value
    })
    const fieldKeyDown = createDerived(() => (event: KeyboardEvent) => {
      if (event.key === 'Enter' || event.key === ',') {
        event.preventDefault()
        add.value([draft.value])
        draft.value = ''
        return
      }
      if (event.key === 'Escape' && draft.value !== '') {
        event.preventDefault()
        draft.value = ''
        return
      }
      if (event.key === 'Backspace' && draft.value === '') {
        const last = values.value[values.value.length - 1]
        if (last !== undefined) remove.value(last)
        return
      }
      if (event.key === 'ArrowLeft' && (event.target as HTMLInputElement).selectionStart === 0) {
        removeButton.value(values.value.length - 1)?.focus()
      }
    })
    const chipKeyDown = createDerived(() => (event: KeyboardEvent, tag: string) => {
      const at = values.value.indexOf(tag)
      if (at === -1) return
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        remove.value(tag)
        return
      }
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        const step = event.key === 'ArrowLeft' ? -1 : 1
        if (at + step === values.value.length) field.value?.focus()
        else if (at + step >= 0) removeButton.value(at + step)?.focus()
      }
    })
    const receivePaste = createDerived(() => (event: ClipboardEvent) => {
      const pasted = event.clipboardData?.getData('text') ?? ''
      if (!/[\n,]+/.test(pasted)) return
      event.preventDefault()
      add.value(pasted.split(/[\n,]+/))
      draft.value = ''
    })
    const pressContainer = createDerived(() => (event: MouseEvent) => {
      if ((event.target as HTMLElement).closest('button, input')) return
      event.preventDefault()
      field.value?.focus()
    })
    const leave = createDerived(() => (event: FocusEvent) => {
      if ((event.currentTarget as HTMLElement).contains(event.relatedTarget as Node | null)) return
      props.onBlur?.(event)
    })
    const chipsOf = createMemo(() => values.value)
    const chipsKey = (tag: string) => tag
    const [chipsLeaving, setChipsLeaving] = createSignal<
      { key: string; item: ReturnType<typeof chipsOf>[number]; at: number }[]
    >([])
    createComputed(
      on(chipsOf, (now, before) => {
        if (before === undefined) return
        const kept = new Set(now.map(chipsKey))
        const leaving = chipsLeaving().filter((entry) => !kept.has(entry.key))
        before.forEach((item, at) => {
          const key = chipsKey(item)
          if (!kept.has(key) && !leaving.some((entry) => entry.key === key))
            leaving.push({ key, item, at })
        })
        setChipsLeaving(leaving)
      }),
    )
    const chips = createMemo(() => {
      const entries = chipsOf().map((item) => ({
        item,
        key: chipsKey(item),
        open: true,
        done: () => {},
      }))
      for (const entry of [...chipsLeaving()].sort((a, b) => a.at - b.at))
        entries.splice(Math.min(entry.at, entries.length), 0, {
          item: entry.item,
          key: entry.key,
          open: false,
          done: () => setChipsLeaving((list) => list.filter((other) => other.key !== entry.key)),
        })
      return entries
    })
    const effect1 = () => {
      settled.value = true
    }
    onMount(effect1)
    let release2: (() => void) | undefined
    const effect2 = () => {
      release2?.()
      const ran = agentMember({
        member: 'TagInput',
        element: () => field.value,
        state: () => ({ value: values.value, disabled: props.disabled, invalid: props.invalid }),
        actions: {
          add: {
            argument: 'text',
            run: (value) =>
              (() => {
                if (/[\n,]/.test(value)) {
                  throw new Error('A tag holds no comma or line break: add each tag on its own.')
                }
                if (atMax.value)
                  throw new Error(`The field holds its maximum of ${props.max} tags.`)
                const tag = props.validate(value)
                if (tag === null) throw new Error(`The field refuses "${value}" as a tag.`)
                if (values.value.includes(tag)) throw new Error(`The field already holds "${tag}".`)
                add.value([value])
              })(),
          },
          clear: () =>
            (() => {
              if (values.value.length > 0) commit.value([])
            })(),
        },
      })
      release2 = () => {
        ran()
      }
    }
    onMount(effect2)
    onCleanup(() => release2?.())
    return (
      <div
        class={styles.container}
        data-size={props.size}
        data-state={atMax.value ? 'at-max' : undefined}
        data-disabled={props.disabled ? '' : undefined}
        data-invalid={props.invalid ? '' : undefined}
        data-refused={refused.value ? '' : undefined}
        data-member="tag-input"
        onmousedown={($event: MouseEvent) => pressContainer.value($event)}
        onfocusout={($event: FocusEvent) => leave.value($event)}
        onanimationend={() => ((refused.value = false), (flashing.value = null))}
      >
        {/* chips */}
        <ul class={styles.chips} ref={chipList.attach}>
          <Each of={chips()} by={(chip) => chip.key} renew>
            {(chip) => (
              <TagInputChip
                tag={chip.item}
                open={chip.open}
                appear={settled.value}
                flash={flashing.value === chip.item}
                disabled={props.disabled}
                removeLabel={props.removeLabel(chip.item)}
                onRemove={() => remove.value(chip.item)}
                onKeyDown={($event) => chipKeyDown.value($event, chip.item)}
                onDone={() => chip.done()}
              />
            )}
          </Each>
        </ul>
        {/* field */}
        <input
          class={styles.input}
          type="text"
          value={draft.value}
          placeholder={values.value.length === 0 ? props.placeholder : undefined}
          readonly={atMax.value}
          disabled={props.disabled}
          id={props.id}
          aria-label={props['aria-label']}
          aria-labelledby={props['aria-labelledby']}
          aria-describedby={[props['aria-describedby'], countId.value].filter(Boolean).join(' ')}
          aria-required={props['aria-required']}
          aria-invalid={props.invalid ? true : undefined}
          oninput={($event: InputEvent) => receive.value($event)}
          onkeydown={($event: KeyboardEvent) => fieldKeyDown.value($event)}
          onpaste={($event: ClipboardEvent) => receivePaste.value($event)}
          ref={field.attach}
        />
        {/* count */}
        <span class={styles.reader} id={countId.value}>
          {atMax.value ? `Maximum of ${props.max} added` : `${values.value.length} added`}
        </span>
        {/* announcer */}
        <span class={styles.reader} aria-live="polite">
          {announcement.value}
        </span>
        {props.name !== undefined ? (
          <input
            type="hidden"
            name={props.name}
            value={values.value.join(',')}
            disabled={props.disabled}
          />
        ) : null}
      </div>
    )
  })
}

TagInput.controlKind = 'field'
